import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Visual regression testing","description":"","frontmatter":{"docSection":"contributors","docType":"guide","audiences":["contributor"],"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/testing-visual.md"},"headers":[],"relativePath":"testing-visual.md","filePath":"testing-visual.md"}'),o={name:"testing-visual.md"};function n(r,e,l,c,d,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="visual-regression-testing" tabindex="-1">Visual regression testing <a class="header-anchor" href="#visual-regression-testing" aria-label="Permalink to &quot;Visual regression testing&quot;">​</a></h1><p>Sovereign uses <a href="https://playwright.dev" target="_blank" rel="noreferrer">Playwright</a> screenshot comparisons for local visual regression testing, per <a href="./rfcs/0059-local-visual-regression-testing.html">RFC 0059</a>. It has two tiers:</p><ul><li><strong>Tier 1 — component visuals</strong> (<code>packages/ui/__tests__/visual/</code>): a curated baseline set of <code>@sovereignfs/ui</code> components and gallery screens, captured directly against Storybook&#39;s isolated iframe. No app, no database.</li><li><strong>Tier 2 — runtime smoke</strong> (root <code>__tests__/visual/</code>): a small cross-runtime suite covering auth, shell/Launcher, Account, Console, overlay presentation, and mobile nav layout.</li></ul><p>Both tiers are deliberately <strong>not exhaustive</strong>. Behavior and data correctness stay the job of unit tests and <a href="./testing-e2e.html"><code>__tests__/e2e/</code></a> — visual tests exist only to catch accidental layout/style regressions in a stable, curated set of screens.</p><h2 id="running-locally" tabindex="-1">Running locally <a class="header-anchor" href="#running-locally" aria-label="Permalink to &quot;Running locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Everything (Tier 1 then Tier 2):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:visual</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Tier 1 only — fast, no app/DB required:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @sovereignfs/ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:visual</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Tier 2 only:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config=playwright.visual.config.ts</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Update baselines intentionally (never run this as a side effect of a normal check):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:visual:update</span></span></code></pre></div><p>Tier 1 starts its own Storybook dev server (<code>storybook:visual</code>, port <code>6100</code> — distinct from the regular <code>storybook</code> script&#39;s <code>6006</code>, so both can run side by side). Tier 2 reuses <code>__tests__/e2e/global-setup.ts</code> and <code>fixtures.ts</code> for pre-authenticated pages, so it needs the same local setup as <code>pnpm test:e2e</code> (sqld running — see <code>pnpm dev</code>&#39;s own sqld bootstrap, or <code>docker-compose.yml</code>).</p><h2 id="baseline-update-workflow" tabindex="-1">Baseline update workflow <a class="header-anchor" href="#baseline-update-workflow" aria-label="Permalink to &quot;Baseline update workflow&quot;">​</a></h2><p>Screenshot baselines (<code>*-snapshots/*.png</code>) are source artifacts, committed to the repo. Updating them is an intentional review act:</p><ol><li>Make the intended visual change.</li><li>Run <code>pnpm test:visual:update</code> (or the scoped Tier 1/Tier 2 variant).</li><li><strong>Review the diff.</strong> A baseline PNG changing is a real part of the code review — look at the actual image diff, don&#39;t just accept it because the command ran.</li><li>Commit the updated <code>*-snapshots/*.png</code> files alongside the change that caused them.</li></ol><p><code>pnpm test:visual</code> (no <code>:update</code>) is what CI runs, and what you should run before any PR that touches <code>packages/ui</code>, the runtime shell, or a first-party plugin&#39;s layout — it fails loudly on any unintended diff, with expected/actual/diff images attached to the failure.</p><h2 id="known-limitation-—-cross-platform-font-rendering" tabindex="-1">Known limitation — cross-platform font rendering <a class="header-anchor" href="#known-limitation-—-cross-platform-font-rendering" aria-label="Permalink to &quot;Known limitation — cross-platform font rendering&quot;">​</a></h2><p>Playwright&#39;s snapshot filenames are platform-suffixed (<code>*-darwin.png</code> on macOS, <code>*-linux.png</code> in CI). This repo&#39;s committed baselines were generated on macOS. A Linux CI run will not find a matching baseline and fails with &quot;snapshot doesn&#39;t exist&quot; rather than a real pixel diff — this is expected until a maintainer runs <code>pnpm test:visual:update</code> once from a Linux environment (<code>.github/workflows/visual.yml</code> supports this via <code>workflow_dispatch</code> with <code>updateSnapshots: true</code>) to produce the matching <code>-linux.png</code> baselines. Font rendering differs enough between the two that macOS-generated baselines cannot be reused as-is for a Linux comparison; <code>expect.toHaveScreenshot</code>&#39;s <code>maxDiffPixelRatio: 0.02</code> tolerance absorbs run-to-run anti-aliasing noise on the <em>same</em> platform, not cross-platform differences. See RFC 0059&#39;s open question on per-platform tolerance policy.</p><p><strong>Practical effect:</strong> until that calibration pass happens, <code>pnpm test:visual</code> is a local developer check (or a CI check run manually / via <code>workflow_dispatch</code>), not a blocking gate — <code>.github/workflows/visual.yml</code> is <code>workflow_call</code>-only and intentionally not wired into <code>publish-images.yml</code> yet, unlike <code>e2e.yml</code>.</p><h2 id="filename-convention" tabindex="-1">Filename convention <a class="header-anchor" href="#filename-convention" aria-label="Permalink to &quot;Filename convention&quot;">​</a></h2><p>Visual specs use <code>*.visual.spec.ts</code>, not <a href="./rfcs/0010-test-organization.html">RFC 0010</a>&#39;s originally reserved <code>*.visual.test.tsx</code> — the latter would match Vitest&#39;s <code>*.test.{ts,tsx}</code> include globs (<code>vitest.config.ts</code>), and Vitest would then try to run a Playwright-only spec file as a unit test. <code>*.spec.ts</code> mirrors <code>__tests__/e2e/</code>&#39;s own convention and is excluded from Vitest&#39;s <code>include</code> the same way. <code>vitest.config.ts</code> also explicitly excludes both visual test directories, documenting the intent rather than relying only on the suffix mismatch.</p><h2 id="what-s-covered" tabindex="-1">What&#39;s covered <a class="header-anchor" href="#what-s-covered" aria-label="Permalink to &quot;What&#39;s covered&quot;">​</a></h2><h3 id="tier-1-—-packages-ui-tests-visual-components-visual-spec-ts" tabindex="-1">Tier 1 — <code>packages/ui/__tests__/visual/components.visual.spec.ts</code> <a class="header-anchor" href="#tier-1-—-packages-ui-tests-visual-components-visual-spec-ts" aria-label="Permalink to &quot;Tier 1 — \`packages/ui/__tests__/visual/components.visual.spec.ts\`&quot;">​</a></h3><p>Design System Overview (component gallery) and Token Gallery screens, plus one representative state each for: NavTabs (default + the mobile many-tabs layout), PageHeader, Card (interactive), FormField (error state), Checkbox (disabled+checked), EmptyState, Avatar. Light and dark theme for every entry except the mobile-only NavTabs case.</p><h3 id="tier-1-—-packages-ui-tests-visual-overlays-visual-spec-ts" tabindex="-1">Tier 1 — <code>packages/ui/__tests__/visual/overlays.visual.spec.ts</code> <a class="header-anchor" href="#tier-1-—-packages-ui-tests-visual-overlays-visual-spec-ts" aria-label="Permalink to &quot;Tier 1 — \`packages/ui/__tests__/visual/overlays.visual.spec.ts\`&quot;">​</a></h3><p>Open/visible states for Dialog, Drawer, and Popover — these only render their interesting visual state on interaction, so a default-args screenshot alone would just show a closed trigger button. Both themes.</p><h3 id="tier-2-—-root-tests-visual" tabindex="-1">Tier 2 — root <code>__tests__/visual/</code> <a class="header-anchor" href="#tier-2-—-root-tests-visual" aria-label="Permalink to &quot;Tier 2 — root \`__tests__/visual/\`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Spec</th><th>Covers</th></tr></thead><tbody><tr><td><code>auth.visual.spec.ts</code></td><td>Unauthenticated login page</td></tr><tr><td><code>shell.visual.spec.ts</code></td><td>Launcher grid (desktop), shell header/footer (mobile viewport)</td></tr><tr><td><code>account.visual.spec.ts</code></td><td>Account profile (full-page fallback) and overlay presentation</td></tr><tr><td><code>console.visual.spec.ts</code></td><td>Console settings and system health pages</td></tr><tr><td><code>mobile-nav.visual.spec.ts</code></td><td>Mobile apps drawer, open state</td></tr></tbody></table><h2 id="adding-a-new-visual-test" tabindex="-1">Adding a new visual test <a class="header-anchor" href="#adding-a-new-visual-test" aria-label="Permalink to &quot;Adding a new visual test&quot;">​</a></h2><p>Add one when a component or screen&#39;s visual contract is stable enough to be worth protecting — not for every prop permutation. Per RFC 0059:</p><ul><li>Prefer masking or seeding away dynamic content (timestamps, random IDs) over accepting a noisy diff.</li><li>Keep Tier 2 additions to layout-level smoke, not full workflow coverage — that&#39;s e2e&#39;s job.</li><li>No broad React DOM snapshots (<code>toMatchSnapshot()</code> on a rendered component/page) — see RFC 0059&#39;s snapshot policy for the narrow cases where a text snapshot (not a screenshot) is appropriate (generated registries, manifest validation output, normalized email HTML/text, config JSON).</li></ul>`,26)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
